def retain (value : Nat) : Nat :=
  let local :=
    value
  in
    local;

inductive Gate : Type := | GateOpen : Gate | GateClosed : Gate;
inductive Side : Type := | SideLeft : Side | SideRight : Side;
def select (flag : Gate) : Side := match flag with | GateOpen => SideLeft | GateClosed => SideLeft end;

inductive Gate : Type := | GateOpen : Gate | GateClosed : Gate;
